problem:
Problem description
- There is a single-period blending and selling planning problem with a finite set of raw materials and a finite set of final products.
- Let $$\mathcal{R}$$ be the set of raw materials and let $$\mathcal{P}$$ be the set of products.
- A designated subset of raw materials, denoted by $$\mathcal{R}^{(1)} \subseteq \mathcal{R}$$, must be mixed first in an intermediate tank.
- A designated raw material, denoted by $$r^{(2)} \in \mathcal{R}$$, must be added after the first-stage blend to complete the production of each product.
- Each raw material $$r \in \mathcal{R}$$ has sulfur content $$s_r$$, purchase cost $$c_r$$, and available supply limit $$u_r$$.
- Each product $$p \in \mathcal{P}$$ has selling price $$v_p$$, sulfur-content limit $$\bar{s}_p$$, and market demand limit $$d_p$$.
- The planning goal is to maximize total profit, defined as total sales revenue minus total raw material purchasing cost.
- The production plan must respect material availability, demand limits, product quality limits, and the required two-stage mixing sequence.
- Only nonnegative production and allocation quantities are allowed.
- A solution is represented by:
  - $$x_{r,p}^{(1)}$$: the quantity of first-stage raw material $$r \in \mathcal{R}^{(1)}$$ allocated to product $$p \in \mathcal{P}$$.
  - $$x_{p}^{(2)}$$: the quantity of the second-stage raw material $$r^{(2)}$$ allocated to product $$p \in \mathcal{P}$$.
  - $$q_p$$: the quantity of product $$p \in \mathcal{P}$$ produced and sold.
  - $$\Pi$$: the total profit of the plan.

Input Format
{
  "sets": {
    "raw_materials": {
      "symbol": "$$\\mathcal{R}$$",
      "meaning": "identifiers of all raw materials"
    },
    "products": {
      "symbol": "$$\\mathcal{P}$$",
      "meaning": "identifiers of all final products"
    },
    "first_stage_materials": {
      "symbol": "$$\\mathcal{R}^{(1)}$$",
      "meaning": "raw materials that must be mixed in the first stage"
    },
    "second_stage_material": {
      "symbol": "$$r^{(2)}$$",
      "meaning": "the raw material added in the second stage"
    },
    "planning_horizon": {
      "symbol": "$$\\mathcal{T}$$",
      "meaning": "single planning period"
    }
  },
  "parameters": {
    "sulfur_content": {
      "symbol": "$$s_r$$",
      "shape": "$$|\\mathcal{R}|$$",
      "meaning": "sulfur content of raw material $$r$$"
    },
    "purchase_cost": {
      "symbol": "$$c_r$$",
      "shape": "$$|\\mathcal{R}|$$",
      "meaning": "purchase cost per ton of raw material $$r$$"
    },
    "selling_price": {
      "symbol": "$$v_p$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "selling price per ton of product $$p$$"
    },
    "sulfur_cap": {
      "symbol": "$$\\bar{s}_p$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "maximum allowed sulfur content for product $$p$$"
    },
    "supply_limit": {
      "symbol": "$$u_r$$",
      "shape": "$$|\\mathcal{R}|$$",
      "meaning": "maximum available supply of raw material $$r$$; use $$+\infty$$ for unlimited supply"
    },
    "demand_limit": {
      "symbol": "$$d_p$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "maximum market demand for product $$p$$"
    }
  },
  "objective": {
    "symbol": "$$\\Pi$$",
    "meaning": "total profit to maximize"
  }
}

Output Format
{
  "solution": {
    "first_stage_allocation": {
      "symbol": "$$x_{r,p}^{(1)}$$",
      "shape": "$$|\\mathcal{R}^{(1)}| \\times |\\mathcal{P}|$$",
      "meaning": "quantity of each first-stage raw material allocated to each product"
    },
    "second_stage_allocation": {
      "symbol": "$$x_{p}^{(2)}$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "quantity of the second-stage raw material allocated to each product"
    },
    "production_quantity": {
      "symbol": "$$q_p$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "quantity produced and sold for each product"
    },
    "profit": {
      "symbol": "$$\\Pi$$",
      "shape": "scalar",
      "meaning": "total profit of the selected production plan"
    }
  }
}

Example(s)

Input 1
{
  "sets": {
    "raw_materials": ["RM_A", "RM_B", "RM_C", "RM_D"],
    "products": ["P_A", "P_B"],
    "first_stage_materials": ["RM_A", "RM_B", "RM_D"],
    "second_stage_material": "RM_C",
    "planning_horizon": "single period"
  },
  "parameters": {
    "sulfur_content_percent": {
      "RM_A": 3,
      "RM_B": 1,
      "RM_C": 2,
      "RM_D": 1
    },
    "purchase_cost_thousand_yuan_per_ton": {
      "RM_A": 6,
      "RM_B": 16,
      "RM_C": 10,
      "RM_D": 15
    },
    "selling_price_thousand_yuan_per_ton": {
      "P_A": 9.15,
      "P_B": 9.15
    },
    "sulfur_cap_percent": {
      "P_A": 2.5,
      "P_B": 1.5
    },
    "supply_limit_tons": {
      "RM_A": "Infinity",
      "RM_B": "Infinity",
      "RM_C": "Infinity",
      "RM_D": 50
    },
    "demand_limit_tons": {
      "P_A": 100,
      "P_B": 200
    }
  }
}
